<script setup>
import { computed,nextTick,onUnmounted,reactive,ref,watch } from 'vue';import { useRoute } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import { createAdmin,deleteAdmin,listAdmin,updateAdmin } from '../../api/admin';import { options,text,formatDate } from '../../utils/enums';import PageHeader from '../../components/PageHeader.vue';import AppPagination from '../../components/AppPagination.vue';import { messageOf } from '../../utils/request'
const route=useRoute();const resource=computed(()=>route.meta.resource);const state=reactive({list:[],total:0,pageNum:1,pageSize:10,keyword:'',category:'',loading:false,error:''});const open=ref(false);const form=reactive({});const formRef=ref(null);const saving=ref(false);const deletingId=ref(null);const scopeLabels={ALL:'全部用户',CLIENT:'客户',AGENT:'代理人',ADMIN:'管理员'};const config=computed(()=>({
  'service-products':{title:'服务产品',name:'serviceName',type:'serviceType',group:'serviceType',defaults:{serviceNo:'',serviceName:'',serviceType:'PATENT_APPLICATION',targetType:'',description:'',processDesc:'',officialFee:0,agencyFee:0,estimatedCycle:'',requiredMaterials:'',advantages:'',status:1}},
  'success-cases':{title:'成功案例',name:'caseName',type:'serviceType',group:'serviceType',defaults:{caseNo:'',caseName:'',serviceType:'PATENT_APPLICATION',clientIndustry:'',technicalField:'',highlights:'',result:'',grantDate:'',description:'',publishStatus:1}},
  announcements:{title:'公告管理',name:'title',type:'announcementType',group:'announcementType',defaults:{announcementNo:'',title:'',announcementType:'BUSINESS',targetScope:'ALL',content:'',publishTime:'',startDate:'',endDate:'',isTop:0,status:1}},
}[resource.value]));
const rules=computed(()=>{
  const required=resource.value==='service-products'?['serviceNo','serviceName','serviceType']:resource.value==='success-cases'?['caseNo','caseName','serviceType']:['announcementNo','title','announcementType','targetScope','content']
  const result=Object.fromEntries(required.map(key=>[key,[{required:true,whitespace:true,message:'此项不能为空',trigger:['blur','change']}]]))
  const limits={serviceNo:50,serviceName:200,targetType:200,estimatedCycle:100,caseNo:50,caseName:200,clientIndustry:100,technicalField:200,announcementNo:50,title:200}
  for(const [key,max] of Object.entries(limits)) result[key]=[...(result[key]||[]),{max,message:`最多输入 ${max} 字`,trigger:'blur'}]
  for(const key of ['officialFee','agencyFee']) result[key]=[{validator:(_,value,done)=>{if(value!=null&&(!Number.isFinite(value)||value<0||value>9999999999.99))done(new Error('费用须为非负金额，最多 10 位整数和 2 位小数'));else done()},trigger:'change'}]
  result.endDate=[{validator:(_,value,done)=>{if(form.startDate&&value&&value<form.startDate)done(new Error('结束日期不能早于开始日期'));else done()},trigger:'change'}]
  return result
})
let requestId=0
const load=async()=>{
  const current=++requestId;state.loading=true;state.error=''
  try{const r=await listAdmin(resource.value,{pageNum:state.pageNum,pageSize:state.pageSize,keyword:state.keyword.trim()||undefined,[config.value.type]:state.category||undefined});if(current===requestId){state.list=r.data.list;state.total=r.data.total}}
  catch(e){if(current===requestId)Object.assign(state,{list:[],total:0,error:messageOf(e)})}finally{if(current===requestId)state.loading=false}
}
const edit=(row={})=>{if(saving.value)return;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,config.value.defaults,row);open.value=true;nextTick(()=>formRef.value?.clearValidate())}
const save=async()=>{
  if(saving.value)return;saving.value=true;const target=resource.value
  try{
    if(!await formRef.value.validate().catch(()=>false)||target!==resource.value)return
    const payload=Object.fromEntries(Object.keys(config.value.defaults).map(key=>[key,typeof form[key]==='string'?form[key].trim()||null:form[key]]))
    form.id?await updateAdmin(target,form.id,payload):await createAdmin(target,payload)
    ElMessage.success('内容已保存');if(target===resource.value){open.value=false;await load()}
  }catch(e){ElMessage.error(messageOf(e))}finally{saving.value=false}
}
const remove=async(row)=>{
  if(deletingId.value!==null)return;deletingId.value=row.id;const target=resource.value
  try{
    await ElMessageBox.confirm('确认删除该内容？','删除确认',{type:'warning'});await deleteAdmin(target,row.id);ElMessage.success('内容已删除')
    if(target===resource.value){state.pageNum=Math.min(state.pageNum,Math.max(1,Math.ceil((state.total-1)/state.pageSize)));await load()}
  }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(messageOf(e))}finally{deletingId.value=null}
}
watch(resource,()=>{Object.assign(state,{pageNum:1,keyword:'',category:'',list:[],total:0});open.value=false;load()},{immediate:true})
onUnmounted(()=>{requestId++})
</script>
<template><div class="page"><PageHeader :title="config.title" description="维护游客端公开展示内容"><el-button type="primary" :disabled="saving || deletingId!==null" @click="edit()">新增内容</el-button></PageHeader><div class="toolbar"><div class="filters"><el-input v-model="state.keyword" placeholder="名称或标题" clearable @keyup.enter="state.pageNum=1;load()"/><el-select v-model="state.category" clearable placeholder="全部分类" @change="state.pageNum=1;load()"><el-option v-for="o in options(config.group)" :key="o.value" v-bind="o"/></el-select><el-button @click="state.pageNum=1;load()">查询</el-button></div></div><el-alert v-if="state.error" :title="state.error" type="error" show-icon :closable="false"/><div class="table-wrap"><el-table v-loading="state.loading" :data="state.list"><el-table-column prop="id" label="ID" width="70"/><el-table-column :prop="config.name" label="名称/标题" min-width="240"/><el-table-column label="分类" width="140"><template #default="{row}">{{text(config.group,row[config.type])}}</template></el-table-column><el-table-column label="展示状态" width="140"><template #default="{row}"><el-tag :type="(row.publishStatus??row.status)===1?'success':'info'">{{ (row.publishStatus??row.status)===1?'启用':'隐藏' }}</el-tag><el-tag v-if="row.isTop===1" type="warning">置顶</el-tag></template></el-table-column><el-table-column label="更新时间" width="160"><template #default="{row}">{{formatDate(row.updateTime||row.publishTime)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button link :disabled="saving || deletingId!==null" @click="edit(row)">编辑</el-button><el-button link type="danger" :loading="deletingId===row.id" :disabled="saving || deletingId!==null" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><AppPagination v-model:page="state.pageNum" v-model:size="state.pageSize" :total="state.total" @change="load"/><el-dialog v-model="open" :title="form.id?'编辑内容':'新增内容'" width="min(720px,94vw)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><el-form ref="formRef" :model="form" :rules="rules" :disabled="saving" class="form-grid" label-position="top"><template v-if="resource==='service-products'"><el-form-item label="服务编号" prop="serviceNo"><el-input v-model="form.serviceNo"/></el-form-item><el-form-item label="服务名称" prop="serviceName"><el-input v-model="form.serviceName"/></el-form-item><el-form-item label="服务类型" prop="serviceType"><el-select v-model="form.serviceType"><el-option v-for="o in options('serviceType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="适用对象" prop="targetType"><el-input v-model="form.targetType"/></el-form-item><el-form-item label="官方费用" prop="officialFee"><el-input-number v-model="form.officialFee" :min="0" :max="9999999999.99" :precision="2"/></el-form-item><el-form-item label="代理费用" prop="agencyFee"><el-input-number v-model="form.agencyFee" :min="0" :max="9999999999.99" :precision="2"/></el-form-item><el-form-item label="预计周期" prop="estimatedCycle"><el-input v-model="form.estimatedCycle"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item class="span-2" label="服务说明"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item class="span-2" label="服务流程"><el-input v-model="form.processDesc" type="textarea"/></el-form-item><el-form-item class="span-2" label="所需材料"><el-input v-model="form.requiredMaterials" type="textarea"/></el-form-item><el-form-item class="span-2" label="服务优势"><el-input v-model="form.advantages" type="textarea"/></el-form-item></template><template v-else-if="resource==='success-cases'"><el-form-item label="案例编号" prop="caseNo"><el-input v-model="form.caseNo"/></el-form-item><el-form-item label="案例名称" prop="caseName"><el-input v-model="form.caseName"/></el-form-item><el-form-item label="服务类型" prop="serviceType"><el-select v-model="form.serviceType"><el-option v-for="o in options('serviceType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="客户行业" prop="clientIndustry"><el-input v-model="form.clientIndustry"/></el-form-item><el-form-item label="技术领域" prop="technicalField"><el-input v-model="form.technicalField"/></el-form-item><el-form-item label="授权日期"><el-date-picker v-model="form.grantDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item class="span-2" label="案例简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item class="span-2" label="案件亮点"><el-input v-model="form.highlights" type="textarea"/></el-form-item><el-form-item class="span-2" label="处理结果"><el-input v-model="form.result" type="textarea"/></el-form-item><el-form-item label="公开状态"><el-switch v-model="form.publishStatus" :active-value="1" :inactive-value="0"/></el-form-item></template><template v-else><el-form-item label="公告编号" prop="announcementNo"><el-input v-model="form.announcementNo"/></el-form-item><el-form-item label="公告标题" prop="title"><el-input v-model="form.title"/></el-form-item><el-form-item label="公告类型" prop="announcementType"><el-select v-model="form.announcementType"><el-option v-for="o in options('announcementType')" :key="o.value" v-bind="o"/></el-select></el-form-item><el-form-item label="目标范围" prop="targetScope"><el-select v-model="form.targetScope"><el-option v-for="(label,value) in scopeLabels" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="发布时间"><el-date-picker v-model="form.publishTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="有效状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期" prop="endDate"><el-date-picker v-model="form.endDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="置顶"><el-switch v-model="form.isTop" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item class="span-2" label="公告内容" prop="content"><el-input v-model="form.content" type="textarea" :rows="5"/></el-form-item></template></el-form><template #footer><el-button :disabled="saving" @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
